insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata)
values
('social-studies','ss-toolkit-sba-blueprint','social-studies-toolkit','SBA Toolkit 1: From Problem to Research Plan','Build a focused research problem, justify it, choose a method and design a workable sample.',10,true,'{"support":true,"syllabus":{"source":"CXC 14/G/SYLL 22","area":"SBA and exam support"},"lesson":{"objectives":["Turn a syllabus-linked issue into a clear research problem with no more than two variables.","Explain a relevant reason for selecting the issue.","Choose and justify a suitable method of investigation.","Describe a realistic sample and sampling procedure.","Protect privacy and avoid research questions that pressure or stigmatise respondents."],"introduction":"The Social Studies SBA is not a long essay. It is a guided research project. The strongest projects begin with a narrow question that can actually be investigated in a school or community, then choose a method that matches the information needed.","sections":[{"title":"What the current CXC SBA requires","paragraphs":["The current syllabus requires one guided research project based on a syllabus topic, usually connected to a social or economic process, situation or problem in the school or immediate community. The report should not exceed 1,000 words, excluding charts, graphs, tables and pictures.","Students may work individually or in small groups, but the work must remain authentic and must be guided and monitored by the teacher."]},{"title":"Step 1: state the problem","paragraphs":["A good problem is clear, focused and identifies the issue and target population. CXC advises that the problem statement should contain no more than two variables.","Weak: ''Social media is ruining students.'' Stronger: ''What relationship exists between time spent on social media and reported homework completion among Grade 10 students at School X?'' The stronger version is neutral, measurable and identifies a target population."]},{"title":"Step 2: explain why the topic matters","paragraphs":["The reason for choosing the area should be relevant to the problem. It may arise from an observed school or community issue, a need for better information, or a concern connected to the syllabus. Avoid vague reasons such as ''because it is interesting'' unless you explain why the issue matters."]},{"title":"Step 3: choose the method","bullets":["Questionnaire: useful for collecting comparable responses from several people efficiently.","Interview schedule: useful when more detailed explanations are needed.","Observation checklist: useful when behaviour or conditions can be observed directly.","Documentary search: useful when existing records, reports or documents can answer the question."]},{"title":"Step 4: define the sample","paragraphs":["State who will participate, how many persons are in the sample, relevant characteristics such as age group or class, and how they were selected. The sampling method should fit the research question and the access available to the student.","A convenient sample may be easier to reach but less representative. A random approach can reduce some selection bias when a suitable sampling frame exists. Explain the limitation honestly instead of pretending the sample is perfect."]}],"keyPoints":["The project should be based on a clear syllabus-linked problem or issue.","A problem statement should be focused and contain no more than two variables.","The investigation method must suit the type of evidence needed.","Sampling choices affect how confidently findings can be generalised.","Research involving people requires respectful, non-coercive data collection."],"summary":"A strong SBA begins with alignment: research question → method → instrument → sample. If these four pieces do not fit each other, the rest of the project becomes difficult.","flashcards":[{"front":"What is the maximum current Social Studies SBA length?","back":"1,000 words, excluding charts, graphs, tables and pictures."},{"front":"How many variables should the SBA problem statement contain at most?","back":"No more than two variables."},{"front":"Name four accepted investigation methods.","back":"Questionnaire, interview schedule, observation checklist and documentary search."},{"front":"What should a sample description include?","back":"Who was sampled, sample size, relevant characteristics and how participants were selected."},{"front":"Why must the research method match the question?","back":"The method must collect evidence capable of answering the stated problem."}],"interactiveModels":[{"id":"ss-sba-problem-builder","type":"social-studies","mode":"choice","title":"SBA Problem Builder","items":[{"prompt":"Which problem statement is strongest?","choices":["Why are students lazy?","What factors affect homework completion among Grade 10 students at School X?","Students use too much social media.","Why is education important?"],"correctIndex":1,"explanation":"It identifies a specific issue and target population without assuming the answer."},{"context":"You want detailed explanations from 12 parents about after-school supervision.","prompt":"Which method is most suitable?","choices":["Interview schedule","Weather map","Population census","Election ballot"],"correctIndex":0,"explanation":"An interview schedule supports detailed, guided responses from a manageable number of participants."},{"context":"You want to record whether students wash hands before using a school canteen.","prompt":"Which method fits best?","choices":["Observation checklist","Essay question","Manifesto","Family tree"],"correctIndex":0,"explanation":"The behaviour can be directly observed using consistent checklist items."}]}]}}'::jsonb),
('social-studies','ss-toolkit-instruments-sampling','social-studies-toolkit','SBA Toolkit 2: Questionnaires, Interviews, Observation and Sampling','Write instruments that produce usable data and recognise validity, reliability and sampling limitations.',20,true,'{"support":true,"syllabus":{"source":"CXC 14/G/SYLL 22","area":"SBA and exam support"},"lesson":{"objectives":["Construct clear, well-sequenced data-collection items.","Use open and closed questions appropriately.","Identify leading, double-barrelled, vague and unnecessary questions.","Explain basic validity and reliability concerns.","Evaluate how sample size and sampling method affect conclusions."],"introduction":"Bad questions create bad data. A beautiful graph cannot repair an instrument that confused respondents or pushed them toward an answer. The instrument must collect information that directly answers the research problem.","sections":[{"title":"Closed and open questions","paragraphs":["Closed questions provide defined response options and are efficient for counting patterns. Open questions allow respondents to explain ideas in their own words and can reveal reasons that fixed options may miss.","Use each type for a purpose. A questionnaire made entirely of open questions can become difficult to code, while one made entirely of closed questions may miss useful explanations."]},{"title":"Common instrument problems","bullets":["Leading: ''Don''t you agree the canteen food is unhealthy?'' suggests the desired answer.","Double-barrelled: ''Is the canteen cheap and nutritious?'' asks two things at once.","Vague: ''Do you exercise regularly?'' may mean different things to different people unless ''regularly'' is defined.","Irrelevant: a question about favourite music does not help a project about transport to school unless a clear link exists.","Intrusive: unnecessary sensitive questions can harm trust and should not be asked simply because the researcher is curious."]},{"title":"Sequence matters","paragraphs":["Begin with easy, relevant questions. Group related items together. Put more sensitive items later where necessary. Make response options complete and non-overlapping when possible. Test the instrument with a small pilot group before full data collection if your teacher permits."]},{"title":"Validity and reliability","paragraphs":["Validity asks whether the method and instrument are actually measuring what the research intends to measure. Reliability concerns consistency: would the approach produce reasonably consistent results if repeated under similar conditions?","A biased sample, unclear question or inconsistent interview procedure can weaken the quality of findings."]},{"title":"Sampling limitations","paragraphs":["A sample does not need to include everyone, but the method matters. If a survey about all students is administered only to members of one club, the sample may not represent the wider school. State limitations honestly and avoid generalising beyond the evidence."]}],"keyPoints":["Instrument items must be clear, relevant, neutral and logically sequenced.","Open and closed questions serve different purposes.","Validity concerns whether the research measures what it intends to measure.","Reliability concerns consistency.","Sampling limitations should be acknowledged rather than hidden."],"summary":"Before collecting data, ask: Does every question help answer the research problem? Could wording confuse or influence the respondent? Can the responses be analysed sensibly?","flashcards":[{"front":"What is a closed question?","back":"A question with defined response options that can be counted or classified easily."},{"front":"What is an open question?","back":"A question allowing respondents to answer in their own words."},{"front":"What is a double-barrelled question?","back":"One item that asks about two different issues at the same time."},{"front":"What does validity mean in research?","back":"The extent to which the method actually measures what the study intends to measure."},{"front":"What does reliability mean?","back":"The consistency of a method or instrument under similar conditions."},{"front":"Why pilot an instrument?","back":"To identify confusing wording, missing options or practical problems before full collection."}],"interactiveModels":[{"id":"ss-sba-instrument-audit","type":"social-studies","mode":"choice","title":"Instrument Audit","items":[{"prompt":"Which question is double-barrelled?","choices":["How do you travel to school?","Is the bus service reliable and affordable?","How long is your journey?","What is your age group?"],"correctIndex":1,"explanation":"Reliability and affordability are two separate issues and could receive different answers."},{"prompt":"Which item is most neutral?","choices":["Why is the school bus terrible?","How satisfied are you with the school bus service?","Don''t you think the bus is too expensive?","Responsible students use the bus, right?"],"correctIndex":1,"explanation":"It asks for the respondent''s judgement without inserting the researcher''s opinion."},{"prompt":"A survey of the whole school uses only members of the football team.","choices":["The sample may be biased","The study is automatically invalid","The questionnaire becomes an interview","The sample is a census"],"correctIndex":0,"explanation":"One club may differ from the wider student population, limiting representativeness."}]}]}}'::jsonb),
('social-studies','ss-toolkit-data-findings','social-studies-toolkit','SBA Toolkit 3: Presenting Data, Analysis, Findings and Recommendations','Turn raw data into accurate displays, explain what the evidence means and build recommendations that genuinely follow from findings.',30,true,'{"support":true,"syllabus":{"source":"CXC 14/G/SYLL 22","area":"SBA and exam support"},"lesson":{"objectives":["Choose at least three different appropriate forms of data presentation.","Label tables, graphs and charts correctly.","Analyse data in relation to the research question.","Write three findings supported by the data.","Make two recommendations based on findings and outline implementation of one.","Refer to at least two relevant sources in analysis where required by the marking scheme."],"introduction":"The SBA is marked on the logic connecting the stages. Your findings must come from your data. Your recommendations must come from your findings. If the chain breaks, the project becomes a collection of unrelated sections.","sections":[{"title":"Three different forms","paragraphs":["The current CXC guidelines require at least three different appropriate forms of data presentation. For example, a table, a bar graph and a pie chart are three forms. A horizontal bar graph and a vertical bar graph count as the same form for this purpose.","Every display needs an accurate title, labels, units and values. Use a form that suits the data instead of choosing one because it looks attractive."]},{"title":"Analysis and interpretation","paragraphs":["Analysis identifies patterns, comparisons and relationships. Interpretation explains what those patterns mean in relation to the research question. Use actual numbers or percentages from the display as evidence.","A strong paragraph might say: ''18 of the 30 respondents, or 60%, reported studying for less than one hour on school nights. This suggests that limited study time was common in the sample.'' The statement reports evidence before interpreting it."]},{"title":"Findings","paragraphs":["CXC requires three statements of findings based on the data presented. A finding should answer part of the research problem and should not introduce new information that was never measured.","Finding: ''Most respondents who reported more than two hours of daily social-media use also reported completing homework after 9 p.m.'' This is stronger than ''Social media is bad for students'' because it stays within the observed data."]},{"title":"Recommendations","paragraphs":["The project requires two recommendations based on the findings, and an implementation strategy for one. A recommendation should address a problem shown by the research, not a generic idea copied from the internet.","Implementation explains how one recommendation could be carried out: who should act, what should be done, what resources may be needed, and how progress could be checked."]},{"title":"Keep the evidence chain visible","bullets":["Research problem asks the question.","Instrument gathers relevant evidence.","Data displays organise the evidence.","Analysis explains the evidence.","Findings state what was discovered.","Recommendations respond to those findings.","Implementation turns one recommendation into an actionable plan."]}],"keyPoints":["Use at least three different forms of data presentation.","Data displays must be accurate, titled and labelled.","Analysis must refer back to the research question.","Three findings must be based on the data.","Two recommendations must follow from findings, with one implementation strategy."],"summary":"Before submitting, draw arrows between every finding and the data that supports it, then between every recommendation and the finding it addresses. If an arrow cannot be drawn, revise the section.","flashcards":[{"front":"How many different data-presentation forms are required?","back":"At least three different appropriate forms."},{"front":"Do horizontal and vertical bar graphs count as two forms?","back":"No. They are the same form for the SBA requirement."},{"front":"How many findings are required?","back":"Three findings based on the presented data."},{"front":"How many recommendations are required?","back":"Two recommendations based on findings."},{"front":"What extra step is required for one recommendation?","back":"Explain an implementation strategy for carrying it out."},{"front":"What should analysis refer back to?","back":"The research question and the evidence shown in the data."}],"interactiveModels":[{"id":"ss-sba-evidence-chain","type":"social-studies","mode":"choice","title":"Evidence Chain Check","items":[{"context":"Data: 21 of 30 respondents said transport cost makes attendance difficult.","prompt":"Which finding is best supported?","choices":["Transport cost was a common reported attendance difficulty in this sample","The government does not care about students","All students need free transport","Transport is the only cause of absence"],"correctIndex":0,"explanation":"It stays within the measured evidence and the sample."},{"context":"Finding: Most respondents reported missing breakfast because they leave home very early.","prompt":"Which recommendation is most directly connected?","choices":["Start a school breakfast support programme and evaluate take-up","Build a new football field","Change the national voting age","Increase tourism advertising"],"correctIndex":0,"explanation":"The recommendation directly responds to the finding."},{"prompt":"Which set satisfies the ''three different forms'' requirement?","choices":["Three bar graphs","Bar graph + table + pie chart","Vertical bar + horizontal bar + grouped bar","Three tables"],"correctIndex":1,"explanation":"The requirement is for different forms, not three versions of the same form."}]}]}}'::jsonb),
('social-studies','ss-toolkit-exam-strategy','social-studies-toolkit','Exam Toolkit: Paper 1, Structured Responses and Essays','Learn how to read Social Studies questions, use command words, work with sources and build concise evidence-based responses.',40,true,'{"support":true,"syllabus":{"source":"CXC 14/G/SYLL 22","area":"SBA and exam support"},"lesson":{"objectives":["Use common command words correctly.","Separate knowledge recall from application and evaluation.","Answer source-based and data questions using evidence provided.","Plan concise structured responses.","Build an extended response with clear points, explanation, Caribbean application and a reasoned conclusion."],"introduction":"Knowing the content is only half the job. Social Studies rewards students who answer the exact question asked. A student can know a topic well and still lose marks by defining when asked to explain, listing when asked to assess, or writing a long paragraph that never uses the source.","sections":[{"title":"Command words","bullets":["Define: give the precise meaning of a term.","Identify/State: give the required name, fact or point directly.","Describe: give relevant characteristics or features.","Explain: show how or why, usually through a cause, relationship or consequence.","Compare: show relevant similarities and/or differences as required.","Assess/Evaluate: use criteria and evidence to make a reasoned judgement, not a personal guess.","Justify: give reasons showing why a choice, strategy or conclusion is appropriate."]},{"title":"Paper 1 habits","paragraphs":["Read every option. Watch for qualifiers such as MOST, BEST, NOT and EXCEPT. Use the stem and any table, graph, image or scenario before relying on memory. Eliminate options that contradict definitions or evidence.","When the paper provides statistical data, answer from the data unless the question explicitly asks for an explanation. Do not invent causes that are not shown."]},{"title":"Structured responses","paragraphs":["Match the number of distinct points to the marks where the structure suggests it. State the point, explain it, then apply it to the scenario or Caribbean context. Avoid repeating the same idea in different words.","If a question asks for two reasons, two clear explained reasons are stronger than five unexplained phrases."]},{"title":"Extended responses","paragraphs":["Plan before writing. A useful paragraph pattern is Point → Explain → Caribbean example or application → Link back to the question. Use examples to prove or clarify the point, not as decoration.","A conclusion should answer the question based on the arguments already made. It should not introduce a completely new point."]},{"title":"Source-based questions","paragraphs":["Quote only the small piece you need or paraphrase it. Name the pattern or issue, then support your statement with a figure, category or detail from the source. Distinguish what the source proves from what it merely suggests."]}],"keyPoints":["Answer the command word, not the topic in general.","Explanation shows how or why; evaluation applies criteria and evidence.","Use source evidence explicitly.","Caribbean examples should clarify the concept.","A reasoned conclusion follows from the evidence already discussed."],"summary":"Before writing, underline the command word and the exact subject of the question. After writing, ask: did I answer that command, and did I support it with explanation or evidence?","flashcards":[{"front":"What does ''explain'' require?","back":"Show how or why something happens, usually through a cause, link or consequence."},{"front":"What does ''evaluate'' require?","back":"Apply relevant criteria and evidence to reach a reasoned judgement."},{"front":"What does ''justify'' require?","back":"Give reasons showing why a choice, strategy or conclusion is appropriate."},{"front":"What should you do first with a data question?","back":"Read the title, source, units, categories and values before interpreting."},{"front":"What is a useful essay paragraph pattern?","back":"Point → Explain → Caribbean example/application → Link to the question."},{"front":"What should a conclusion do?","back":"Answer the question from the arguments and evidence already presented."}],"interactiveModels":[{"id":"ss-exam-command-words","type":"social-studies","mode":"classify","title":"Command Word Trainer","categories":["Define","Describe","Explain","Evaluate","Justify"],"items":[{"label":"Give the meaning of ''brain drain''.","category":"Define"},{"label":"Give the main characteristics of a formal social group.","category":"Describe"},{"label":"Show how migration may affect a Caribbean country of origin.","category":"Explain"},{"label":"Use evidence to judge how effective a proposed disaster strategy may be.","category":"Evaluate"},{"label":"Give reasons why your recommended strategy is appropriate for the stated problem.","category":"Justify"}]}]}}'::jsonb)
